sample:
// const: 再代入しない変数(基本はこちら)
const language = "JavaScript";
console.log(language);

// let: あとから値を入れ直す変数
let count = 0;
console.log(count);
count = count + 1;  // 再代入
console.log(count);

// const に再代入するとエラーになります
// language = "Python";  // TypeError になるのでコメントにしています

// Python:     name = "太郎"
// JavaScript: const name = "太郎";
const name = "太郎";
console.log(name);

exercise.starter:
// 1. const で city を作る

// 2. let で year を作る

// 3. year を再代入する

exercise.answer:
// 変えない値は const、あとで入れ直す値だけ let にします
const city = "東京";
let year = 2025;
console.log(city);
console.log(year);
// let で宣言したので再代入できます(const だとここでエラーになります)
year = 2026;
console.log(year);
